//go:build windows

package external

import (
	"path/filepath"

	"golang.org/x/sys/windows"
)

// путьДляTor приводит путь к форме, которую tor под Windows точно
// переживёт: к короткому имени 8.3.
//
// Причина выяснена на живом tor 0.4.9.11. Он открывает файлы через
// однобайтовую кодировку, а не UTF-16: путь с кириллицей превращается в
// кракозябру, и tor отказывается стартовать — «Error creating directory
// ...: No such file or directory». У пользователя с русским именем
// учётной записи это происходило бы всегда. Короткое имя заодно убирает
// пробелы, из-за которых пришлось бы кавычить путь и экранировать слэши.
//
// Тонкость, которая однажды стоила отказа на домашней машине с профилем
// «C:\Users\Регистратура»: короткое имя Windows выдаёт только для того,
// что существует. Файлы control_port и tor.log мы прямо перед запуском
// удаляем — старые увели бы нас на мёртвый порт, — и короткого имени у
// них взяться неоткуда. В torrc уходил полный кириллический путь: tor
// не мог создать файл и выходил, не открыв control-порт, а приложение
// показывало «процесс tor завершился, не открыв control-порт».
//
// Поэтому, если короткого имени у самого пути нет, укорачиваем каталог
// (он-то существует) и приставляем имя файла. Имена наших файлов —
// латиница без пробелов, укорачивать в них нечего.
//
// Если короткого имени нет и у каталога (файловая система их не
// хранит), возвращаем исходный путь: пусть лучше tor пожалуется сам,
// чем мы молча подставим то, чего нет.
func путьДляTor(путь string) string {
	абсолютный, err := filepath.Abs(путь)
	if err != nil {
		абсолютный = путь
	}

	if короткий := короткоеИмя(абсолютный); короткий != "" {
		return короткий
	}

	каталог, имя := filepath.Split(абсолютный)
	if каталог == "" || имя == "" {
		return абсолютный
	}
	if короткий := короткоеИмя(filepath.Clean(каталог)); короткий != "" {
		return filepath.Join(короткий, имя)
	}
	return абсолютный
}

// короткоеИмя спрашивает у Windows имя 8.3. Пустая строка значит «его
// нет»: либо путь не существует, либо том короткие имена не хранит.
func короткоеИмя(путь string) string {
	широкий, err := windows.UTF16PtrFromString(путь)
	if err != nil {
		return ""
	}
	длина, err := windows.GetShortPathName(широкий, nil, 0)
	if err != nil || длина == 0 {
		return ""
	}
	буфер := make([]uint16, длина)
	if _, err := windows.GetShortPathName(широкий, &буфер[0], длина); err != nil {
		return ""
	}
	return windows.UTF16ToString(буфер)
}
